@dataclass(frozen=True)
class PaymentMethod:
    code: str
    symbol: str
    network: str
    price_id: str
    address: str
    address_kind: str
    precision: int = 8
    token_contract: str = ""

    def public(self) -> dict:
        return {
            "code": self.code,
            "symbol": self.symbol,
            "network": self.network,
            "icon": "/assets/payments/"+self.code+".svg",
            "address_hint": {
                "evm": "0x…",
                "tron": "T…",
                "near": "имя.near или ID аккаунта",
                "ltc": "ltc1… / L… / M…",
            }[self.address_kind],
            "token_contract": self.token_contract,
        }


BSC_WALLET = "0x72166383914799fF63582eC556f5Db5856654EEb"
TRON_WALLET = "TMxiRH2sFJfjjbFwVYgqMf7JErmTk8KaL4"
NEAR_WALLET = "8218f2973b35c681b966135fd8296e4693d2aa7fbe1039e9e5d8e42ef0ab9bfd"
PAYMENT_METHODS = {
    method.code: method for method in (
        PaymentMethod("ltc", "LTC", "Litecoin", "litecoin", LTC_ADDRESS, "ltc"),
        PaymentMethod("usdt_bsc", "USDT", "BNB Smart Chain · BEP20", "tether", BSC_WALLET, "evm",
                      token_contract="0x55d398326f99059fF775485246999027B3197955"),
        PaymentMethod("usdc_bsc", "USDC", "BNB Smart Chain · BEP20", "usd-coin", BSC_WALLET, "evm",
                      token_contract="0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d"),
        PaymentMethod("trx", "TRX", "TRON", "tron", TRON_WALLET, "tron", 6),
        PaymentMethod("bnb", "BNB", "BNB Smart Chain", "binancecoin", BSC_WALLET, "evm"),
        PaymentMethod("near", "NEAR", "NEAR Protocol", "near", NEAR_WALLET, "near"),
        PaymentMethod("usdt_trc20", "USDT", "TRON · TRC20", "tether", TRON_WALLET, "tron", 6,
                      token_contract="TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t"),
    )
}


def payment_method(code: str) -> PaymentMethod:
    if not isinstance(code, str) or code not in PAYMENT_METHODS:
        raise Fault("Выберите поддерживаемую валюту и сеть")
    return PAYMENT_METHODS[code]


def payment_amount(kopeks: int, rate: Decimal, method: PaymentMethod) -> str:
    if not rate.is_finite() or rate <= 0:
        raise Fault("Источник вернул некорректный курс", 503)
    quantum = Decimal(1).scaleb(-method.precision)
    amount = (Decimal(kopeks) / 100 / rate).quantize(quantum, rounding=ROUND_CEILING)
    return format(amount, "f")


def payment_address_valid(address: str, method: PaymentMethod) -> bool:
    if method.address_kind == "ltc":
        return validate_address(address)
    if method.address_kind == "evm":
        return bool(re.fullmatch(r"0x[0-9a-fA-F]{40}", address)) and int(address[2:], 16) != 0
    if method.address_kind == "near":
        return 2 <= len(address) <= 64 and bool(re.fullmatch(r"[a-z0-9]+(?:[._-][a-z0-9]+)*", address))
    if not re.fullmatch(r"T[1-9A-HJ-NP-Za-km-z]{33}", address):
        return False
    alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
    number = 0
    for character in address:
        number = number*58 + alphabet.index(character)
    raw = number.to_bytes((number.bit_length()+7)//8, "big")
    checksum = hashlib.sha256(hashlib.sha256(raw[:-4]).digest()).digest()[:4]
    return len(raw) == 25 and raw[0] == 0x41 and hmac.compare_digest(raw[-4:], checksum)


def payment_details(row) -> str:
    method = payment_method(dict(row).get("payment_method", "ltc"))
    contract = f"\nКонтракт токена: <code>{method.token_contract}</code>" if method.token_contract else ""
    return (f"{row['ltc_amount']} {method.symbol}\nСеть: {method.network}"
            f"\nАдрес: <code>{html.escape(row['address'])}</code>{contract}")


def now() -> int:
    return int(time.time())


def uid() -> str:
    return uuid.uuid4().hex


def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def rub(amount: int) -> str:
    return format(Decimal(amount) / 100, ".2f")


def money_input(value: Any, *, allow_zero: bool = False) -> int:
    text = str(value).strip().replace(" ", "").replace("₽", "").replace(",", ".")
    if not re.fullmatch(r"\d{1,9}(?:\.\d{1,2})?", text):
        raise Fault("Укажите сумму в рублях, не больше двух знаков после запятой")
    result = int(Decimal(text) * 100)
    if result < (0 if allow_zero else 1) or result > 100_000_000:
        raise Fault("Сумма должна быть от 0,01 до 1 000 000 ₽")
    return result


def ltc_amount(kopeks: int, rate: Decimal) -> str:
    return payment_amount(kopeks, rate, PAYMENT_METHODS["ltc"])


def validate_address(address: str) -> bool:
    if not isinstance(address, str) or not 26 <= len(address) <= 90:
        return False
    if address.startswith(("L", "M")):
        alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
        try:
            number = 0
            for char in address:
                number = number*58+alphabet.index(char)
            raw = number.to_bytes((number.bit_length()+7)//8, "big")
            raw = b"\x00"*(len(address)-len(address.lstrip("1")))+raw
            return len(raw) == 25 and raw[0] in (48, 50) and hmac.compare_digest(raw[-4:], hashlib.sha256(hashlib.sha256(raw[:-4]).digest()).digest()[:4])
        except (ValueError, OverflowError):
            return False
    try:
        if address.lower() != address and address.upper() != address:
            return False
        address = address.lower()
        hrp, data = address.rsplit("1", 1)
        if hrp != "ltc" or len(data) < 7:
            return False
        charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
        digits = [charset.index(c) for c in data]
        values = [ord(c) >> 5 for c in hrp]+[0]+[ord(c) & 31 for c in hrp]+digits
        check = 1
        for value in values:
            top = check >> 25
            check = ((check & 0x1ffffff) << 5)^value
            for i, generator in enumerate((0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3)):
                if top >> i & 1:
                    check ^= generator
        version = digits[0]
        if version > 16 or check != (1 if version == 0 else 0x2bc830a3):
            return False
        acc = bits = 0
        program = []
        for digit in digits[1:-6]:
            acc = ((acc << 5)|digit)&4095
            bits += 5
            while bits >= 8:
                bits -= 8
                program.append((acc >> bits)&255)
        if bits >= 5 or (acc << (8-bits))&255:
            return False
        return 2 <= len(program) <= 40 and (version != 0 or len(program) in (20, 32))
    except (ValueError, IndexError):
        return False


class Fault(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def load_env(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text("utf-8").splitlines():
        if not line.strip() or line.lstrip().startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        if re.fullmatch(r"[A-Z][A-Z0-9_]*", key.strip()):
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


