async def maintenance(store: Store):
    while True:
        try:
            with store.transaction() as db:
                db.execute("DELETE FROM web_sessions WHERE expires_at<=?", (now(),))
                db.execute("DELETE FROM login_codes WHERE expires_at<=? OR used=1", (now(),))
                db.execute("DELETE FROM bot_states WHERE expires_at<=?", (now(),))
                db.execute("DELETE FROM phone_flows WHERE expires_at<=?", (now(),))
                db.execute("DELETE FROM processed_updates WHERE created_at<?", (now()-7*86400,))
                db.execute("UPDATE jobs SET result_enc='',result_expires=0 WHERE result_expires>0 AND result_expires<=?", (now(),))
        except sqlite3.Error:
            LOG.warning("Database maintenance delayed")
        await asyncio.sleep(30)


def configure_interactive() -> None:
    path = Path(__file__).resolve().with_name("acczlol.env")
    load_env(path)
    if not sys.stdin.isatty():
        raise SystemExit("Run --setup in a terminal, or set BOT_TOKEN, PUBLIC_URL, TELEGRAM_API_ID and TELEGRAM_API_HASH as environment variables.")
    print("acczLOL · настройка сервера. Секретные значения не выводятся.")
    values: dict[str, str] = {}
    prompts = (
        ("BOT_TOKEN", "Токен от @BotFather", True, True),
        ("PUBLIC_URL", "HTTPS-адрес сервера (например https://shop.example.com)", False, True),
        ("TELEGRAM_API_ID", "API ID с my.telegram.org", False, True),
        ("TELEGRAM_API_HASH", "API Hash с my.telegram.org", True, True),
        ("ADMIN_IDS", "Telegram ID админов через запятую (необязательно)", False, False),
        ("ADMIN_KEY", "Новый админ-ключ (пусто — использовать заданный ранее)", True, False),
        ("COINGECKO_API_KEY", "CoinGecko Demo API key (необязательно)", True, False),
        ("DATA_DIR", "Каталог данных (пусто — рядом с bot.py)", False, False),
    )
    for key, title, private, required in prompts:
        while True:
            existing = os.environ.get(key, "")
            value = (getpass.getpass if private else input)(title+(" [Enter: оставить]" if existing else "")+": ").strip() or existing
            if required and not value:
                print("Это значение нужно для рабочего подключения.")
                continue
            if any(c in value for c in "\r\n\x00"):
                print("Значение должно занимать одну строку.")
                continue
            if key == "BOT_TOKEN" and not re.fullmatch(r"\d{5,20}:[A-Za-z0-9_-]{20,}", value):
                print("Проверьте формат токена.")
                continue
            if key == "PUBLIC_URL":
                parsed = urllib.parse.urlsplit(value)
                if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.query or parsed.fragment or parsed.path not in ("", "/"):
                    print("Нужен HTTPS origin без пути, логина и параметров.")
                    continue
                value = value.rstrip("/")
            if key == "TELEGRAM_API_ID" and (not value.isdigit() or int(value) <= 0):
                print("API ID — положительное целое число.")
                continue
            if key == "TELEGRAM_API_HASH" and not re.fullmatch(r"[a-fA-F0-9]{32}", value):
                print("API Hash содержит 32 шестнадцатеричных символа.")
                continue
            if key == "ADMIN_IDS" and value and not re.fullmatch(r"\s*\d+(?:\s*,\s*\d+)*\s*", value):
                print("Укажите числовые ID через запятую.")
                continue
            values[key] = value
            break
    if path.exists():
        answer = input("Обновить существующий acczlol.env? [y/N]: ").lower().strip()
        if answer not in ("y", "yes", "д", "да"):
            print("Настройка отменена.")
            return
    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    fd = os.open(path, flags, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as stream:
        stream.write("# acczLOL runtime configuration. Keep private; do not commit.\n")
        for key, value in values.items():
            if value:
                stream.write(key+"="+value+"\n")
    with contextlib.suppress(OSError):
        path.chmod(0o600)
    print("Настройка сохранена. Запуск: python bot.py. Подключите HTTPS reverse proxy к порту 8080.")


def check_configuration(settings: Settings, role: str) -> None:
    if settings.demo:
        return
    problems = []
    if role in ("all", "web", "bot"):
        if not re.fullmatch(r"\d{5,20}:[A-Za-z0-9_-]{20,}", settings.bot_token):
            problems.append("BOT_TOKEN")
        parsed = urllib.parse.urlsplit(settings.public_url)
        if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.query or parsed.fragment or parsed.path not in ("", "/"):
            problems.append("PUBLIC_URL (HTTPS origin)")
    if role in ("all", "agent"):
        if settings.api_id <= 0:
            problems.append("TELEGRAM_API_ID")
        if not re.fullmatch(r"[a-fA-F0-9]{32}", settings.api_hash):
            problems.append("TELEGRAM_API_HASH")
        try:
            import telethon  # noqa: F401
        except ImportError:
            problems.append("dependency Telethon")
    if not 1 <= settings.worker_concurrency <= 16:
        problems.append("AGENT_CONCURRENCY (1–16)")
    if not validate_address(settings.ltc_address):
        problems.append("valid Litecoin address")
    if settings.webhook_url:
        if not re.fullmatch(r"[A-Za-z0-9_-]{16,256}", settings.webhook_secret):
            problems.append("WEBHOOK_SECRET (16–256 letters/digits/_/-)")
        if settings.webhook_url != settings.public_url+"/telegram/webhook":
            problems.append("WEBHOOK_URL must equal PUBLIC_URL/telegram/webhook")
    if problems:
        raise SystemExit("acczLOL: configure "+", ".join(problems)+". Run python bot.py --setup. For local preview only: python bot.py --demo.")


async def configure_bot(bot: TelegramAPI):
    me = await bot.call("getMe")
    bot.settings.bot_username = me["username"]
    await bot.call("setChatMenuButton", {"menu_button": {"type": "web_app", "text": "acczLOL", "web_app": {"url": bot.settings.public_url+"/"}}})
    await bot.call("setMyCommands", {"commands": [
        {"command": "start", "description": "Открыть меню acczLOL"},
        {"command": "balance", "description": "Мой баланс"},
        {"command": "login", "description": "Код входа в acczLOL на ПК"},
        {"command": "cancel", "description": "Отменить ввод"},
    ]})
    with contextlib.suppress(Fault, aiohttp.ClientError, asyncio.TimeoutError):
        await bot.call("setMyName", {"name": "acczLOL"})
        await bot.call("setMyDescription", {"description": "acczLOL — каталог Telegram-аккаунтов, баланс, покупки и поддержка в одном Mini App."})
    try:
        await bot.warm_emoji()
    except Exception:
        LOG.warning("Premium emoji unavailable; ordinary emoji fallback enabled")
    if bot.settings.webhook_url:
        await bot.call("setWebhook", {"url": bot.settings.webhook_url, "secret_token": bot.settings.webhook_secret,
            "allowed_updates": ["message", "callback_query"], "drop_pending_updates": False})


async def run_service(args: argparse.Namespace):
    settings = Settings.from_env(args)
    role = "web" if args.web_only else args.role
    # In a demo the SQL worker is also needed to show the purchase transition.
    if settings.demo and args.web_only:
        role = "all"
    check_configuration(settings, role)
    if settings.database_url and not os.environ.get("ENCRYPTION_KEY", "").strip():
        raise SystemExit("Для DATABASE_URL задайте постоянный ENCRYPTION_KEY (Fernet) в ENV. Без него зашифрованные данные потеряются после перезапуска.")
    vault = Vault(settings.data_dir, os.environ.get("ENCRYPTION_KEY", "").strip())
    store = Store(settings.data_dir / "store.sqlite3", vault, settings)
    if settings.demo:
        seed_demo(store)
    assets = embedded_assets()
    if "index.html" not in assets:
        raise SystemExit("Embedded application assets are missing.")
    runner = None
    tasks: list[asyncio.Task] = []
    agent = MTProtoAgent(store, settings)
    stop = asyncio.Event()
    loop = asyncio.get_running_loop()
    for signum in (signal.SIGTERM, signal.SIGINT):
        with contextlib.suppress(NotImplementedError, RuntimeError):
            loop.add_signal_handler(signum, stop.set)
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=25)) as http:
        bot = TelegramAPI(http, settings, store)
        prices = PriceFeed(http, settings)
        try:
            if role in ("all", "bot") and not settings.demo:
                try:
                    await configure_bot(bot)
                except Exception as error:
                    raise SystemExit("Telegram bot connection failed ("+type(error).__name__+"). Check BOT_TOKEN and network access; no token was logged.") from None
            elif role == "web" and settings.bot_token:
                try:
                    me = await bot.call("getMe")
                    settings.bot_username = me["username"]
                    await bot.warm_emoji()
                except Exception:
                    LOG.warning("Bot metadata unavailable; configure BOT_USERNAME for the standalone login link")
            if role in ("all", "web"):
                service = WebService(store, settings, bot, prices, assets)
                runner = web.AppRunner(service.app(), access_log=None)
                await runner.setup()
                await web.TCPSite(runner, args.host, args.port).start()
                LOG.info("acczLOL %s listening on port %d", "DEMO" if settings.demo else "server", args.port)
                if settings.demo:
                    LOG.info("DEMO only: dummy balance and accounts; Litecoin deposits disabled")
            if role in ("all", "agent"):
                tasks.append(asyncio.create_task(agent.run(), name="mtproto-agent"))
            if role in ("all", "bot") and not settings.demo:
                if not settings.webhook_url:
                    tasks.append(asyncio.create_task(bot.polling(assets), name="telegram-polling"))
                tasks.append(asyncio.create_task(bot.outbox(), name="bot-outbox"))
            tasks.append(asyncio.create_task(maintenance(store), name="maintenance"))
            stopper = asyncio.create_task(stop.wait(), name="shutdown")
            done, pending = await asyncio.wait([*tasks, stopper], return_when=asyncio.FIRST_COMPLETED)
            for task in done:
                if task is not stopper:
                    task.result()
                    raise RuntimeError("Background component stopped: "+task.get_name())
            stopper.cancel()
        finally:
            for task in [*tasks, *agent.tasks]:
                task.cancel()
            await asyncio.gather(*tasks, *agent.tasks, return_exceptions=True)
            if runner:
                await runner.cleanup()


class CoreTests(unittest.TestCase):
    """Offline checks: no bot token, real session or payment is used."""
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.settings = Settings(Path(self.tmp.name), admin_key="test-admin")
        self.store = Store(Path(self.tmp.name)/"test.sqlite3", Vault(Path(self.tmp.name)), self.settings)
        self.store.user({"id": 101, "first_name": "Buyer"})
        self.store.user({"id": 102, "first_name": "Other"})
        self.store.user({"id": 103, "first_name": "Admin"})
        self.store.execute("UPDATE users SET balance=100000 WHERE id IN (101,102)")

    def tearDown(self):
        self.tmp.cleanup()

    def account(self, amount: int = 25000) -> str:
        account = self.store.add_account(103, "Test", amount, "test-session-secret", "test-2fa-secret", "new")
        self.store.execute("DELETE FROM jobs WHERE account_id=?", (account,))
        self.store.execute("UPDATE accounts SET state='available',score=80 WHERE id=?", (account,))
        return account

    def purchased(self) -> tuple[str, dict]:
        account = self.account()
        order = self.store.buy(101, account, "test-order-key")
        job = self.store.claim_job("worker-a")
        self.assertTrue(self.store.finish_job(job, "worker-a", {"login": "+10000000000", "username": "owned"}))
        return account, order

    def test_decimal_money_and_litoshi_rounding(self):
        self.assertEqual(money_input("1 234,56 ₽"), 123456)
        self.assertEqual(ltc_amount(10000, Decimal("7000")), "0.01428572")
        self.assertEqual(ltc_amount(10000, Decimal("10000")), "0.01000000")
        for value in ("-1", "1.001", "nan", "1e4", "0"):
            with self.assertRaises(Fault):
                money_input(value)
        with self.assertRaises(Fault):
            ltc_amount(1, Decimal("NaN"))
        self.assertTrue(validate_address(LTC_ADDRESS))
        self.assertFalse(validate_address(LTC_ADDRESS[:-1]+"p"))

    def test_no_plaintext_secrets_in_database(self):
        account = self.account()
        row = self.store.one("SELECT * FROM accounts WHERE id=?", (account,))
        self.assertNotIn("test-session-secret", row["secret_enc"])
        self.assertNotIn("test-2fa-secret", row["secret_enc"])
        self.assertEqual(self.store.vault.open(row["secret_enc"])["session"], "test-session-secret")
        raw = self.store.path.read_bytes()
        self.assertNotIn(b"test-session-secret", raw)
        self.assertNotIn(b"test-2fa-secret", raw)

    def test_purchase_is_idempotent(self):
        account = self.account()
        first = self.store.buy(101, account, "same-request-key")
        second = self.store.buy(101, account, "same-request-key")
        self.assertEqual(first["id"], second["id"])
        self.assertEqual(self.store.one("SELECT balance FROM users WHERE id=101")["balance"], 75000)
        self.assertEqual(len(self.store.query("SELECT * FROM ledger WHERE kind='purchase'")), 1)
        with self.assertRaises(Fault):
            self.store.buy(101, self.account(), "same-request-key")

    def test_concurrent_buyers_cannot_double_sell(self):
        from concurrent.futures import ThreadPoolExecutor
        account = self.account()
        def attempt(user):
            try:
                return self.store.buy(user, account, "parallel-key-"+str(user))["id"]
            except Fault:
                return None
        with ThreadPoolExecutor(max_workers=2) as pool:
            results = list(pool.map(attempt, (101, 102)))
        self.assertEqual(sum(bool(item) for item in results), 1)
        self.assertEqual(len(self.store.query("SELECT * FROM orders")), 1)
        self.assertEqual(self.store.one("SELECT SUM(balance) n FROM users")["n"], 175000)

    def test_failed_delivery_refunds_exactly_once(self):
        account = self.account()
        order = self.store.buy(101, account, "failed-order-key")
        job = self.store.claim_job("worker-a")
        self.store.fail_job(job, "worker-a", "SESSION_EXPIRED")
        self.store.fail_job(job, "worker-a", "SESSION_EXPIRED")
        self.store.refund(103, order["id"], "REPEAT")
        self.assertEqual(self.store.one("SELECT balance FROM users WHERE id=101")["balance"], 100000)
        self.assertEqual(self.store.one("SELECT state FROM orders WHERE id=?", (order["id"],))["state"], "refunded")
        self.assertEqual(len(self.store.query("SELECT * FROM ledger WHERE kind='refund'")), 1)
        self.assertEqual(self.store.one("SELECT state FROM accounts WHERE id=?", (account,))["state"], "attention")

    def test_worker_lease_rejects_stale_completion(self):
        account = self.account()
        self.store.buy(101, account, "lease-order-key")
        stale = self.store.claim_job("worker-old")
        self.store.execute("UPDATE jobs SET lease_until=? WHERE id=?", (now()-2, stale["id"]))
        fresh = self.store.claim_job("worker-new")
        self.assertEqual(fresh["id"], stale["id"])
        self.assertFalse(self.store.finish_job(stale, "worker-old", {"login": "+111"}))
        self.assertTrue(self.store.finish_job(fresh, "worker-new", {"login": "+222"}))
        self.assertEqual(self.store.order_rows(101)[0]["login"], "+222")

    def test_refund_during_worker_does_not_deliver(self):
        account = self.account()
        order = self.store.buy(101, account, "race-refund-key")
        job = self.store.claim_job("worker-a")
        self.store.refund(103, order["id"], "ADMIN_REFUND")
        self.assertFalse(self.store.finish_job(job, "worker-a", {"login": "+111"}))
        with self.assertRaises(Fault):
            self.store.request_code(101, order["id"])

    def test_code_owner_expiry_and_refund_revocation(self):
        account, order = self.purchased()
        with self.assertRaises(Fault):
            self.store.access(102, order["id"])
        with self.assertRaises(Fault):
            self.store.request_code(102, order["id"])
        job_id = self.store.request_code(101, order["id"])
        job = self.store.claim_job("worker-a")
        self.store.finish_job(job, "worker-a", {"code": "12345", "message_id": 15})
        self.assertEqual(self.store.job_result(101, job_id)["code"], "12345")
        with self.assertRaises(Fault):
            self.store.job_result(103, job_id, admin=True)
        self.store.refund(103, order["id"], "TEST")
        with self.assertRaises(Fault):
            self.store.job_result(101, job_id)
        with self.assertRaises(Fault):
            self.store.recheck(103, account)

    def test_expired_code_never_returned(self):
        _, order = self.purchased()
        job_id = self.store.request_code(101, order["id"])
        job = self.store.claim_job("worker-a")
        self.store.finish_job(job, "worker-a", {"code": "12345", "message_id": 12})
        self.store.execute("UPDATE jobs SET result_expires=? WHERE id=?", (now()-1, job_id))
