        row = self.store.create_withdrawal(101, 10000, LTC_ADDRESS, "withdraw-once-key", Decimal("7000"))
        same = self.store.create_withdrawal(101, 10000, LTC_ADDRESS, "withdraw-once-key", Decimal("7000"))
        self.assertEqual(row["id"], same["id"])
        self.assertEqual(self.store.one("SELECT balance FROM users WHERE id=101")["balance"], 90000)
        with self.assertRaises(Fault):
            self.store.review_withdrawal(102, row["id"], True)
