    def test_concurrent_withdrawals_cannot_overdraw(self):
        from concurrent.futures import ThreadPoolExecutor
        def attempt(i):
            try:
                self.store.create_withdrawal(101, 80000, LTC_ADDRESS, "concurrent-withdraw-"+str(i), Decimal("7000"))
                return True
            except Fault:
                return False
        with ThreadPoolExecutor(max_workers=2) as pool:
            results = list(pool.map(attempt, range(2)))
        self.assertEqual(sum(results), 1)
        self.assertEqual(self.store.one("SELECT balance FROM users WHERE id=101")["balance"], 20000)

