class AgentTests(unittest.IsolatedAsyncioTestCase):
    async def test_authorized_session_checks_and_fresh_service_code(self):
        from unittest.mock import patch
        from types import SimpleNamespace as NS
        from telethon.sessions import MemorySession, StringSession
        from telethon.crypto import AuthKey
        from telethon.tl.functions.account import GetPasswordRequest, GetPasswordSettingsRequest, GetAuthorizationsRequest
        with tempfile.TemporaryDirectory() as directory:
            settings = Settings(Path(directory), api_id=12345, api_hash="a"*32, code_wait=1)
            store = Store(Path(directory)/"store.sqlite3", Vault(Path(directory)), settings)
            store.user({"id": 301, "first_name": "Owner"})
            store.execute("UPDATE users SET balance=100000 WHERE id=301")
            session = MemorySession()
            session.set_dc(2, "149.154.167.51", 443)
            session.auth_key = AuthKey(b"y"*256)
            account = store.add_account(301, "Owned", 10000, StringSession.save(session), "verified-password", "new")
            calls = []
            class Client:
                def __init__(self, *args, **kwargs):
                    calls.append("StringSession")
                async def connect(self): calls.append("connect")
                async def disconnect(self): calls.append("disconnect")
                async def is_user_authorized(self): return True
                async def get_me(self): return NS(id=98765, phone="10000000000", username="owner", bot=False)
                async def __call__(self, request):
                    if isinstance(request, GetPasswordRequest): return NS(has_password=True, has_recovery=True)
                    if isinstance(request, GetPasswordSettingsRequest):
                        calls.append("verify-2fa")
                        return NS(email="o***@example.com")
                    if isinstance(request, GetAuthorizationsRequest): return NS(authorizations=[NS(current=True)])
                    raise AssertionError("Unexpected MTProto method")
                async def get_messages(self, entity, limit):
                    calls.append((entity, limit))
                    return [NS(id=88, date=datetime.now(timezone.utc), out=False, raw_text="Login code: 54321.")]
            agent = MTProtoAgent(store, settings)
            with patch("telethon.TelegramClient", Client), patch("telethon.password.compute_check", lambda p, v: NS(password=v)):
                await agent.work(store.claim_job(agent.worker_id))
                self.assertEqual(store.catalog()[0]["score"], 100)
                self.assertIn("verify-2fa", calls)
                order = store.buy(301, account, "agent-real-path-test")
                await agent.work(store.claim_job(agent.worker_id))
                self.assertEqual(store.order_rows(301)[0]["login"], "+10000000000")
                job_id = store.request_code(301, order["id"])
                await agent.work(store.claim_job(agent.worker_id))
                self.assertEqual(store.job_result(301, job_id)["code"], "54321")
                self.assertIn((777000, 8), calls)
                self.assertEqual(store.one("SELECT last_code_message_id FROM accounts WHERE id=?", (account,))["last_code_message_id"], 88)


class PhoneLoginTests(unittest.IsolatedAsyncioTestCase):
    async def test_phone_code_2fa_mail_and_publication(self):
        from unittest.mock import patch, AsyncMock
        from types import SimpleNamespace as NS
        from telethon.sessions import MemorySession, StringSession
        from telethon.crypto import AuthKey
        from telethon import errors
        from telethon.tl import functions, types
        with tempfile.TemporaryDirectory() as directory:
            settings = Settings(Path(directory), api_id=12345, api_hash="a"*32)
            store = Store(Path(directory)/"test.sqlite3", Vault(Path(directory)), settings)
            store.user({"id": 501, "first_name": "Seller"})
            store.user({"id": 502, "first_name": "Other"})
            async with aiohttp.ClientSession() as http:
                login = PhoneLogin(store, settings, http)
                memory = MemorySession()
                memory.set_dc(2, "149.154.167.51", 443)
                memory.auth_key = AuthKey(b"z"*256)
                class Client:
                    session = memory
                    async def connect(self): pass
                    async def disconnect(self): pass
                    async def send_code_request(self, phone):
                        return NS(phone_code_hash="test-phone-hash", type=types.auth.SentCodeTypeApp(length=5))
                    async def sign_in(self, *args, **kwargs):
                        if "password" not in kwargs:
                            raise errors.SessionPasswordNeededError(request=None)
                        if kwargs["password"] != "correct-2fa":
                            raise errors.PasswordHashInvalidError(request=None)
                    async def get_me(self): return NS(id=987654321, phone="12345678900", username="seller", bot=False)
                    async def __call__(self, request):
                        if isinstance(request, functions.account.GetPasswordRequest): return NS(has_password=True)
                        if isinstance(request, functions.account.SendVerifyEmailCodeRequest): return NS(length=6)
                        if isinstance(request, functions.account.VerifyEmailRequest): return NS(email="created@example.test")
                        raise AssertionError(type(request).__name__)
                with patch.object(login, "client", return_value=Client()):
                    started = await login.start(501, {"phone": "+12345678900", "consent": True, "auto_mail": True})
                    flow_id = started["flow_id"]
                    with self.assertRaises(Fault): login.read(502, flow_id)
                    result = await login.action(501, flow_id, "code", {"code": "12345"})
                    self.assertEqual(result["state"], "password")
                    with self.assertRaises(Fault):
                        await login.action(501, flow_id, "password", {"password": "wrong"})
                    result = await login.action(501, flow_id, "password", {"password": "correct-2fa"})
                    self.assertEqual(result["state"], "authorized")
                    self.assertNotIn("password", result)
                    with patch.object(login.mail, "create", new=AsyncMock(return_value={"address": "created@example.test", "password": "email-secret", "id": "mail-id"})), patch.object(login.mail, "messages", new=AsyncMock(return_value=[])):
                        result = await login.action(501, flow_id, "email-send", {"consent": True})
                    self.assertEqual(result["email_status"], "verification_sent")
                    with patch.object(login.mail, "wait_code", new=AsyncMock(return_value={"id": "message-id", "code": "654321"})):
                        result = await login.action(501, flow_id, "email-check", {})
                    self.assertTrue(result["email_bound"])
                    result = await login.action(501, flow_id, "publish", {"price": "200", "title": "Test"})
                    self.assertEqual(result["state"], "published")
                    self.assertEqual(store.one("SELECT seller_id FROM accounts WHERE id=?", (result["account_id"],))["seller_id"], 501)
                    self.assertNotIn("correct-2fa", store.path.read_bytes().decode(errors="ignore"))

    async def test_mailbox_reads_only_telegram_messages(self):
        from unittest.mock import AsyncMock, patch
        async with aiohttp.ClientSession() as http:
            mail = QuickMailbox(http)
            rows = {"hydra:member": [
                {"id": "bad", "from": {"address": "attacker@example.test"}, "createdAt": datetime.now(timezone.utc).isoformat()},
                {"id": "good", "from": {"address": "noreply@telegram.org"}, "createdAt": datetime.now(timezone.utc).isoformat()}]}
            responses = [{"token": "test-token"}, rows, {"subject": "Telegram login code", "text": "Login code: 123456"}]
            with patch.object(mail, "request", new=AsyncMock(side_effect=responses)) as request:
                messages = await mail.messages({"address": "mail@example.test", "password": "test-password"}, now()-60)
            self.assertEqual([m["code"] for m in messages], ["123456"])
            self.assertEqual(request.call_count, 3)


def main():
    parser = argparse.ArgumentParser(description="acczLOL: Telegram bot + Mini App + admin + MTProto session worker in one file")
    parser.add_argument("--setup", action="store_true", help="secure interactive configuration")
    parser.add_argument("--demo", action="store_true", help="isolated dummy-data preview, no real payments or sessions")
    parser.add_argument("--self-test", action="store_true", help="offline unit and HTTP integration tests")
    parser.add_argument("--role", choices=("all", "web", "bot", "agent"), default="all")
    parser.add_argument("--host", default="0.0.0.0")
    parser.add_argument("--port", type=int, default=int(os.environ.get("PORT", "8080")))
    parser.add_argument("--web-only", action="store_true", help="run web process (demo also runs dummy worker)")
    parser.add_argument("--strictPort", action="store_true", help=argparse.SUPPRESS)
    args = parser.parse_args()
    if args.setup:
        configure_interactive()
        return
    if args.self_test:
        suite = unittest.TestSuite()
        for case in (CoreTests, APITests, AgentTests, PhoneLoginTests):
            suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(case))
        result = unittest.TextTestRunner(verbosity=2).run(suite)
        raise SystemExit(0 if result.wasSuccessful() else 1)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    logging.getLogger("telethon").setLevel(logging.ERROR)
    try:
        asyncio.run(run_service(args))
    except KeyboardInterrupt:
        pass
    except OSError as error:
        raise SystemExit("acczLOL could not start: "+str(error)) from None


if __name__ == "__main__":
    main()
